const FYL_STAFF = [
  {
    name: "STERLING",
    role: "Creator / Executive",
    image: "data:image/webp;base64,",
    intro: "",
    promo: "",
    bio: "",
    weapon: "",
    summary: "Sterling is the central figure behind Fight of Your Life. His full Staff profile will populate here as the remaining Sterling cards are added."
  },
  {
    name: "LUTHER",
    role: "Security / Enforcer",
    image: "",
    intro: "",
    promo: "",
    bio: "",
    weapon: "",
    summary: "Luther profile assets coming next."
  },
  {
    name: "LUCAS",
    role: "Staff",
    image: "",
    intro: "",
    promo: "",
    bio: "",
    weapon: "",
    summary: "Lucas profile assets coming next."
  },
  {
    name: "ZADORA",
    role: "Host / Promotional Face",
    image: "",
    intro: "",
    promo: "",
    bio: "",
    weapon: "",
    summary: "Zadora profile assets coming next."
  },
  {
    name: "TIKAYOH",
    role: "Announcer / Hypeman",
    image: "",
    intro: "",
    promo: "",
    bio: "",
    weapon: "",
    summary: "Tikayoh profile assets coming next."
  }
];

(function () {
  const nameEl = document.getElementById("staffName");
  const countEl = document.getElementById("staffCount");
  const imageEl = document.getElementById("staffImage");
  const rosterEl = document.getElementById("staffRoster");
  const host = document.getElementById("staffProfileHost");

  if (!nameEl || !countEl || !imageEl || !rosterEl || !host) return;

  function mediaBlock(label, src, alt) {
    if (!src) return "";
    return `<div class="media-shell"><div class="media-label">${label}</div><img loading="lazy" src="${src}" alt="${alt}"></div>`;
  }

  function renderProfile(i) {
    const s = FYL_STAFF[i];
    if (!s) return;

    document.querySelectorAll("#staffRoster button").forEach((b, idx) => {
      b.classList.toggle("active", idx === i);
    });

    nameEl.textContent = s.name;
    countEl.textContent = "STAFF " + String(i + 1).padStart(2, "0") + " / 05";

    if (s.image) {
      imageEl.src = s.image;
      imageEl.alt = s.name;
      imageEl.style.display = "block";
    } else {
      imageEl.removeAttribute("src");
      imageEl.alt = s.name;
      imageEl.style.display = "none";
    }

    const hasCards = s.intro || s.promo || s.bio || s.weapon;
    host.innerHTML = `
      <section class="content staff-profile profile-active" id="${s.name.toLowerCase()}-staff-profile">
        <div class="section-kicker">FYL STAFF</div>
        <h2>${s.name}</h2>
        <p class="lead">${s.role}</p>
        <p class="copy">${s.summary}</p>
        ${hasCards ? `
          <div class="staff-media-grid">
            <div class="staff-card-stack">
              ${mediaBlock("INTRO CARD", s.intro, s.name + " intro card")}
              ${mediaBlock("PROMO CARD", s.promo, s.name + " promo card")}
            </div>
            <div class="staff-card-stack">
              ${mediaBlock("BIO CARD", s.bio, s.name + " bio card")}
              ${mediaBlock("WEAPON CARD", s.weapon, s.name + " weapon card")}
            </div>
          </div>
        ` : `<div class="staff-placeholder">Additional ${s.name} Staff cards will appear here when added.</div>`}
      </section>`;
  }

  rosterEl.querySelectorAll("button").forEach((btn, i) => {
    btn.addEventListener("click", () => renderProfile(i));
  });

  // Sterling is the default Staff character, just as Grant is the default Fighter.
  renderProfile(0);
})();
